package com.brightloop.quotation;
import com.brightloop.catalog.*;import com.brightloop.plan.Plan;import jakarta.persistence.*;import java.time.Instant;import java.util.ArrayList;import java.util.List;
@Entity @Table(name="quotation_templates") public class QuotationTemplate{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@Column(nullable=false,unique=true,length=140) String name;@Column(length=500) String description;@Column(name="validity_days",nullable=false) int validityDays=14;@Column(name="created_at",nullable=false,updatable=false) Instant createdAt=Instant.now();@OneToMany(mappedBy="template",cascade=CascadeType.ALL,orphanRemoval=true) List<QuotationTemplateLine> lines=new ArrayList<>();protected QuotationTemplate(){}public QuotationTemplate(String name,String desc,int days){this.name=name;description=desc;validityDays=days;}public void addLine(QuotationTemplateLine l){lines.add(l);}public Long getId(){return id;}public String getName(){return name;}public String getDescription(){return description;}public int getValidityDays(){return validityDays;}public List<QuotationTemplateLine> getLines(){return lines;}}
@Entity @Table(name="quotation_template_lines") class QuotationTemplateLine{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="template_id",nullable=false) QuotationTemplate template;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="product_id",nullable=false) Product product;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="plan_id") Plan plan;@ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="variant_id") ProductVariant variant;@Column(nullable=false) int quantity;protected QuotationTemplateLine(){}public QuotationTemplateLine(QuotationTemplate t,Product p,Plan plan,ProductVariant v,int qty){template=t;product=p;this.plan=plan;variant=v;quantity=qty;}public Long getProductId(){return product.getId();}public String productName(){return product.getName();}public Long getPlanId(){return plan==null?null:plan.getId();}public String planName(){return plan==null?null:plan.getName();}public Long getVariantId(){return variant==null?null:variant.getId();}public String variantName(){return variant==null?null:variant.getName();}public int getQuantity(){return quantity;}}
